public int palindromeIndex(String s) {
    if (isPalindrome(s, 0, s.length() - 1)) return -1;
    for (int i = 0; i < s.length(); i++) {
        String candidate = s.substring(0, i) + s.substring(i + 1);
        if (isPalindrome(candidate, 0, candidate.length() - 1)) return i;
    }
    return -1;
}

private boolean isPalindrome(String s, int l, int r) {
    while (l < r) {
        if (s.charAt(l) != s.charAt(r)) return false;
        l++;
        r--;
    }
    return true;
}

