def palindrome_index(self, s: str) -> int:
    def is_pal(l: int, r: int) -> bool:
        while l < r:
            if s[l] != s[r]:
                return False
            l += 1
            r -= 1
        return True

    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return l if is_pal(l + 1, r) else r
        l += 1
        r -= 1
    return -1
